import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { API_BASE } from '../api';

// Helper function to validate image URLs before rendering to prevent OpaqueResponseBlocking
const validateImageUrl = async (url) => {
  try {
    const response = await fetch(url, { 
      method: 'HEAD',
      mode: 'no-cors'
    });
    return response.type !== 'opaque' || response.ok;
  } catch {
    return false;
  }
};

const getValidImageUrl = (post) => {
  console.log('🔍 Getting image URL for post:', post.title);
  
  // Check if featuredImage is a string URL
  if (typeof post.featuredImage === 'string' && post.featuredImage) {
    // If it starts with http, use it directly
    if (post.featuredImage.startsWith('http')) {
      console.log('✅ Using featuredImage URL:', post.featuredImage);
      return post.featuredImage;
    }
    // If it's a relative path, construct full URL
    const baseUrl = 'https://dr-serzhans-psycare.onrender.com';
    const fullUrl = post.featuredImage.startsWith('/') 
      ? `${baseUrl}${post.featuredImage}` 
      : `${baseUrl}/api/media/file/${post.featuredImage}`;
    console.log('✅ Constructed URL from string:', fullUrl);
    return fullUrl;
  }
  
  // Check if featuredImage is an object with URL property
  if (post.featuredImage?.url) {
    console.log('✅ Using featuredImage.url:', post.featuredImage.url);
    return post.featuredImage.url;
  }
  
  // Check other possible image fields
  const otherImageUrl = post.image?.url || post.thumbnail?.url || post.coverImage?.url || post.heroImage?.url;
  if (otherImageUrl) {
    console.log('✅ Using alternative image URL:', otherImageUrl);
    return otherImageUrl;
  }
  
  console.log('❌ No image URL found for post:', post.title);
  return null;
};

const BlogList = () => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [validatedImages, setValidatedImages] = useState({});
  const [imageLoading, setImageLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchPosts = async () => {
      try {
        const response = await fetch(API_BASE);
        if (!response.ok) throw new Error('Failed to fetch blog data');
        const data = await response.json();
        const postsData = data.posts || data;
        setPosts(postsData);
        
        // Get image URLs for all posts (no async validation needed)
        console.log('🖼️ Getting image URLs for blog list...');
        const imageValidation = {};
        
        for (const post of postsData) {
          if (post.id) {
            const validUrl = getValidImageUrl(post);
            imageValidation[post.id] = validUrl;
          }
        }
        
        setValidatedImages(imageValidation);
        setLoading(false);
        setImageLoading(false);
      } catch (error) {
        console.error('Error fetching posts:', error);
        setError(error.message);
        setLoading(false);
        setImageLoading(false);
      }
    };
    fetchPosts();
  }, []);

  if (loading) {
    return (
      <div style={{ 
        textAlign: "center", 
        padding: "40px", 
        fontSize: "1.1rem",
        color: "#666" 
      }}>
        Loading blog posts...
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ 
        textAlign: "center", 
        padding: "40px", 
        maxWidth: "600px",
        margin: "0 auto"
      }}>
        <div style={{
          backgroundColor: "#fff3cd",
          border: "1px solid #ffeaa7",
          borderRadius: "8px",
          padding: "20px",
          marginBottom: "20px"
        }}>
          <h3 style={{ color: "#856404", marginBottom: "10px" }}>
            Blog temporarily unavailable
          </h3>
          <p style={{ color: "#856404", lineHeight: "1.5" }}>
            We're experiencing a technical issue with our blog service. 
            Our team is working to resolve this as quickly as possible.
          </p>
        </div>
        <button
          onClick={() => window.location.reload()}
          style={{
            backgroundColor: "rgb(244, 170, 149)",
            color: "white",
            padding: "10px 20px",
            borderRadius: "20px",
            border: "none",
            fontSize: "1rem",
            fontWeight: "500",
            cursor: "pointer"
          }}
        >
          Try Again
        </button>
      </div>
    );
  }

  if (posts.length === 0) {
    return (
      <div style={{ 
        textAlign: "center", 
        padding: "40px", 
        fontSize: "1.1rem",
        color: "#666" 
      }}>
        No blog posts found.
      </div>
    );
  }

  return (
    <div style={{ 
      maxWidth: "900px", 
      margin: "0 auto", 
      padding: "0 20px" 
    }}>
      <div style={{ 
        display: "grid", 
        gap: "30px",
        gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))" 
      }}>
        {posts.map((post, index) => {
          // Use pre-validated image URL to prevent OpaqueResponseBlocking
          const validatedImageUrl = validatedImages[post.id];
          
          return (
            <article
              key={post.id || index}
              style={{
                backgroundColor: "white",
                borderRadius: "12px",
                overflow: "hidden",
                boxShadow: "0 4px 12px rgba(0, 0, 0, 0.1)",
                border: "1px solid #e0e0e0",
                transition: "transform 0.2s ease, box-shadow 0.2s ease",
                cursor: "pointer"
              }}
              onClick={() => navigate(`/blogs/${post.id}`)}
              onMouseOver={(e) => {
                e.currentTarget.style.transform = "translateY(-4px)";
                e.currentTarget.style.boxShadow = "0 8px 20px rgba(0, 0, 0, 0.15)";
              }}
              onMouseOut={(e) => {
                e.currentTarget.style.transform = "translateY(0)";
                e.currentTarget.style.boxShadow = "0 4px 12px rgba(0, 0, 0, 0.1)";
              }}
            >
              {/* Featured Image with pre-validation */}
              {imageLoading ? (
                <div style={{
                  width: "100%",
                  height: "200px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  backgroundColor: "#f5f5f5",
                  color: "#666",
                  fontStyle: "italic"
                }}>
                  Loading image...
                </div>
              ) : validatedImageUrl ? (
                <div style={{
                  width: "100%",
                  height: "200px",
                  overflow: "hidden"
                }}>
                  <img 
                    src={validatedImageUrl}
                    alt={post.title}
                    style={{
                      width: "100%",
                      height: "100%",
                      objectFit: "cover",
                      transition: "transform 0.2s ease"
                    }}
                    onError={(e) => {
                      console.error('❌ Even validated blog list image failed:', validatedImageUrl);
                      e.target.parentElement.style.display = 'none';
                    }}
                  />
                </div>
              ) : null}
              
              <div style={{ padding: "24px" }}>
                <h2 style={{
                  fontSize: "1.5rem",
                  marginBottom: "12px",
                  color: "#333",
                  lineHeight: "1.3"
                }}>
                  {post.title}
                </h2>
                {post.excerpt && (
                  <p style={{
                    color: "#666",
                    marginBottom: "16px",
                    lineHeight: "1.6",
                    fontSize: "1rem"
                  }}>
                    {post.excerpt}
                  </p>
                )}
                {post.content && (
                  <div style={{
                    color: "#555",
                    lineHeight: "1.6",
                    marginBottom: "16px",
                    fontSize: "0.95rem"
                  }}>
                    <div dangerouslySetInnerHTML={{ 
                      __html: post.content.substring(0, 200) + (post.content.length > 200 ? '...' : '')
                    }} />
                  </div>
                )}
                <div style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginTop: "16px",
                  paddingTop: "16px",
                  borderTop: "1px solid #e0e0e0"
                }}>
                  <small style={{ color: "#888" }}>
                    {post.publishedDate ? 
                      new Date(post.publishedDate).toLocaleDateString() : 
                      post.date ? new Date(post.date).toLocaleDateString() : 
                      'Recently published'
                    }
                  </small>
                  <span style={{
                    color: "rgb(244, 170, 149)",
                    fontSize: "0.9rem",
                    fontWeight: "500"
                  }}>
                    Read more →
                  </span>
                </div>
              </div>
            </article>
          );
        })}
      </div>
    </div>
  );
};

function Blogs() {
  return (
    <div className="main-content">
      {/* Top bar - same style as About.js */}
      <div
        className="full-width-section"
        style={{
          background: "linear-gradient(to bottom, rgb(244, 170, 149),rgb(244, 175, 149), rgb(246, 180, 149), rgb(246, 185, 149))",
          color: "white",
          minHeight: "200px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexDirection: "column",
          textAlign: "center",
          padding: "48px 20px 24px 20px"
        }}
      >
        <h2 style={{ fontSize: "2.5rem", marginBottom: "1rem" }}>Blog</h2>
        <p className="therapy-header-desc">
          Read articles and insights on therapy, mental health, and wellness.
        </p>
      </div>

      {/* Blog content goes here */}
      <div style={{ padding: "40px 0" }}>
        <BlogList />
      </div>
    </div>
  );
}

export default Blogs;